import React from 'react';

import clsx from 'clsx';

import { IUser } from '@apps/Users/@services/users.service';
import {
  getWorkoutsTargetMembers,
  joinToWorkoutTarget,
} from '@apps/Workouts/@services/workoutsTargets.service';
import { IWorkoutTarget } from '@apps/Workouts/@types/workoutsTargets.types';
import { AuthContext } from '@contexts/AuthContext';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohLoader from '@ui-kit/Loader';

interface IWorkoutTargetMembersProps extends React.HTMLAttributes<HTMLDivElement> {
  data: IWorkoutTarget;
  onJoined: (member: IUser) => void;
}

const WorkoutTargetMembers: React.FC<IWorkoutTargetMembersProps> = ({
  data,
  onJoined,
  className,
  ...rest
}) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [members, setMembers] = React.useState<IUser[]>([]);
  const [err, setErr] = React.useState<Error>();

  const authContext = React.useContext(AuthContext);

  const fetchData = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const d = await getWorkoutsTargetMembers(data.id);
      setMembers(d);
    } catch (error) {
      setErr(error as Error);
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  }, [data.id]);

  React.useEffect(() => {
    fetchData();
  }, [data.id]);

  if (isLoading) return <PohLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const handleJoin = () => {
    joinToWorkoutTarget(data.id)
      .then(() => {
        notificationHelper.success('Успех! У вас всё получится!');
        if (!authContext.user) return;
        onJoined(authContext.user);
        setMembers((cur) => [...cur, authContext.user!]);
      })
      .catch(notificationHelper.error);
  };

  return (
    <div {...rest} className={clsx('d-flex align-items-center', className)}>
      {data.is_public &&
        data.date_finish > new Date() &&
        !members.find((x) => x.id === authContext.user?.id) && (
          <PohButton variant={ButtonVariant.Success} onClick={handleJoin} className="me-auto">
            Присоединиться
          </PohButton>
        )}
      {members.map((member) => {
        return (
          <PohAva
            key={member.id}
            src={member.photo}
            alt={[member.name, member.surname].join(' ')}
            title={[member.name, member.surname].join(' ')}
          />
        );
      })}
    </div>
  );
};

export default WorkoutTargetMembers;
